using FlexExtractor;
using System.Reflection;
namespace FlexExtractor.UI;
public sealed class MainForm:Form {
 readonly Label recentFile=new(){Name="RecentFile",Dock=DockStyle.Fill,Text="最近文件：—",AutoEllipsis=true,TextAlign=ContentAlignment.MiddleLeft};
 readonly Label recentStation=new(){Name="RecentStation",Dock=DockStyle.Fill,Text="最近站位：—",AutoEllipsis=true,TextAlign=ContentAlignment.MiddleLeft};
 readonly string configPath=Path.Combine(AppContext.BaseDirectory,"config.json");Config config=new();Engine? engine;bool busy,closing,dark;readonly AntdUI.Button start,settings,theme;readonly Label status=new(){Name="Status",Dock=DockStyle.Fill,Text="请先配置目录与站位",TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true};readonly TextBox log=new(){Name="Log",Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None};readonly Dictionary<string,Label> values=new();readonly System.Windows.Forms.Timer timer=new(){Interval=500};readonly Label clock=new(){AutoSize=true};string lastLog="";
 public MainForm():this(null){}
 public MainForm(Config? initial){Ui.Shell(this,"Flex 报文提取 2.0",new Size(1160,760));MinimumSize=new Size(980,650);var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Padding=new Padding(20),BackColor=Ui.Bg};root.RowStyles.Add(new(SizeType.Absolute,70));root.RowStyles.Add(new(SizeType.Absolute,86));root.RowStyles.Add(new(SizeType.Absolute,184));root.RowStyles.Add(new(SizeType.Absolute,56));root.RowStyles.Add(new(SizeType.Absolute,54));root.RowStyles.Add(new(SizeType.Percent,100));
  var header=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Padding=new Padding(0,8,0,0)};settings=Ui.Action("配置","OpenConfig",(_,_)=>Configure());header.Controls.Add(settings);var resource=Assembly.GetExecutingAssembly().GetManifestResourceNames().Single(x=>x.EndsWith("bosch-logo.png"));using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)!){using var image=Image.FromStream(stream);header.Controls.Add(new PictureBox{Name="Brand",Image=new Bitmap(image),Size=new Size(200,42),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.White,Margin=new Padding(18,0,18,0)});}
  header.Controls.Add(new Label{Text="FLEX 报文提取",AutoSize=true,Font=new Font(Font.FontFamily,18,FontStyle.Bold),Margin=new Padding(8,6,28,0)});theme=Ui.Action("深色模式","Theme",(_,_)=>{dark=!dark;ApplyTheme();});header.Controls.Add(theme);root.Controls.Add(header,0,0);
  var bar=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(0,16,0,16)};bar.ColumnStyles.Add(new(SizeType.Absolute,180));bar.ColumnStyles.Add(new(SizeType.Percent,100));start=Ui.Action("开始提取","StartStop",async(_,_)=>await Toggle(),true);start.Dock=DockStyle.Fill;bar.Controls.Add(start,0,0);status.Padding=new Padding(24,0,0,0);bar.Controls.Add(status,1,0);root.Controls.Add(bar,0,1);
  var cards=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4};foreach(var (key,label) in new[]{("Copied","已复制"),("Failed","失败 / 重试"),("Deleted","过期删除"),("Skipped","已存在 / 范围外")}){cards.ColumnStyles.Add(new(SizeType.Percent,25));var panel=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Margin=new Padding(0,0,14,0),Padding=new Padding(20)};panel.Controls.Add(new Label{Text=label,Dock=DockStyle.Top,Height=30});var value=new Label{Name=key,Text="0",Dock=DockStyle.Bottom,Height=96,Font=new Font("Segoe UI",36,FontStyle.Bold)};panel.Controls.Add(value);cards.Controls.Add(panel);values.Add(key,value);}root.Controls.Add(cards,0,2);
  var recent=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};recent.RowStyles.Add(new(SizeType.Percent,50));recent.RowStyles.Add(new(SizeType.Percent,50));recent.Controls.Add(recentStation,0,0);recent.Controls.Add(recentFile,0,1);root.Controls.Add(recent,0,3);
  var logTitle=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(0,18,0,0)};logTitle.Controls.Add(Ui.Label("运行日志"));clock.Margin=new Padding(30,10,0,0);logTitle.Controls.Add(clock);root.Controls.Add(logTitle,0,4);var logPanel=new Panel{Dock=DockStyle.Fill,Padding=new Padding(18),BackColor=Color.White};logPanel.Controls.Add(log);root.Controls.Add(logPanel,0,5);Controls.Add(root);
  try{if(initial!=null){config=initial;status.Text="测试配置（未启动）";}else if(File.Exists(configPath)){config=Durable.LoadConfig(configPath);status.Text=$"已停止 · 点胶 {config.DispenseItems.Count} / 组装 {config.BindItems.Count}";}}catch(Exception ex)when(ex is IOException or InvalidDataException or System.Text.Json.JsonException or ArgumentException){status.Text="配置错误，禁止启动："+ex.Message;}
  timer.Tick+=(_,_)=>RefreshView();timer.Start();FormClosing+=async(_,e)=>{if(closing)return;e.Cancel=true;if(busy)return;busy=true;start.Enabled=settings.Enabled=false;try{if(engine!=null)await engine.DisposeAsync();closing=true;timer.Stop();Close();}catch(Exception ex){status.Text="无法确认停止，保留锁："+ex.Message;Ui.Error(this,ex);busy=false;}};
 }
 async Task Toggle(){if(busy)return;busy=true;start.Enabled=settings.Enabled=false;try{if(engine!=null){await engine.DisposeAsync();engine=null;start.Text="开始提取";status.Text="已停止";}else{config=Durable.LoadConfig(configPath);var fresh=new Engine(config);fresh.Start();engine=fresh;start.Text="停止提取";status.Text="监控中";}}catch(Exception ex)when(ex is IOException or InvalidDataException or System.Text.Json.JsonException or ArgumentException or InvalidOperationException or UnauthorizedAccessException){Ui.Error(this,ex);status.Text="操作失败："+ex.Message;}finally{busy=false;start.Enabled=true;settings.Enabled=engine==null;}}
 void Configure(){if(engine!=null||busy)return;using var editor=new ConfigEditor(config);if(editor.ShowDialog(this)!=DialogResult.OK)return;try{using var lease=new OwnerLease();Durable.SaveConfig(configPath,editor.Edited);config=editor.Edited;status.Text="配置已保存；请点开始提取";}catch(Exception ex)when(ex is IOException or InvalidDataException or UnauthorizedAccessException){Ui.Error(this,ex);}}
 void RefreshView(){clock.Text=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");if(engine==null)return;var s=engine.Snapshot;values["Copied"].Text=s.Copied.ToString();values["Failed"].Text=s.Failed.ToString();values["Deleted"].Text=s.Deleted.ToString();values["Skipped"].Text=s.Skipped.ToString();recentFile.Text="最近文件："+(s.RecentFile.Length>0?s.RecentFile:"—");recentStation.Text="最近站位："+(s.RecentStation.Length>0?s.RecentStation:"—");status.Text=s.Status;var text=string.Join(Environment.NewLine,engine.Lines);if(text!=lastLog){lastLog=text;log.Text=text;log.SelectionStart=log.TextLength;log.ScrollToCaret();}}
 void ApplyTheme(){AntdUI.Config.Mode=dark?AntdUI.TMode.Dark:AntdUI.TMode.Light;theme.Text=dark?"浅色模式":"深色模式";void Paint(Control c){if(c.Name=="Brand")return;c.BackColor=dark?Color.FromArgb(23,31,45):c is Panel||c==log?Color.White:Ui.Bg;c.ForeColor=dark?Color.FromArgb(230,235,244):Ui.Ink;foreach(Control child in c.Controls)Paint(child);}Paint(this);Invalidate(true);}
 protected override void Dispose(bool disposing){if(disposing){timer.Dispose();foreach(var image in Controls.Cast<Control>().SelectMany(Walk).OfType<PictureBox>().Select(x=>x.Image))image?.Dispose();}base.Dispose(disposing);}
 static IEnumerable<Control> Walk(Control root){yield return root;foreach(Control c in root.Controls)foreach(var x in Walk(c))yield return x;}
}
